def build():
    nav='<a href="index.html">Home</a><a href="ch1.html">Ch 1</a><a href="ch2.html">Ch 2</a><a href="ch3.html">Ch 3</a><a href="ch4.html">Ch 4</a><a href="predicted.html">Predicted Models</a><a href="exam.html">Solved Sample</a><a href="quiz.html">Question Bank</a><a href="cheatsheet.html">Cheat Sheet</a>'
    out=[f'''<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>3 Predicted Exam Models | ٣ نماذج متوقعة</title><link rel="stylesheet" href="css/style.css"></head><body><header class="topbar"><div class="topbar-in"><a class="brand" href="index.html"><span class="logo">⚡</span><span>Ethical Hacking<small>Focused Final Review</small></span></a><nav class="nav">{nav}</nav></div></header><main class="wrap narrow"><div class="page-head"><span class="kicker">Priority Revision · المراجعة الأهم</span><h1>3 Fresh Predicted Exam Models</h1><p class="h1-ar">٣ نماذج جديدة متوقعة — بنفس أسلوب الاختبار ومع الحل</p><p class="lede">Built from all four lecture chapters after analyzing the photographed paper’s exact structure and wording style. Each model contains <b>8 MCQs + 8 True/False + a three-part scenario</b>. Questions are bilingual; answers include concise explanations and slide references.</p><p class="lede lede-ar">مبنية من الفصول الأربعة بعد تحليل تنسيق الورقة المصورة وأسلوب صياغتها. كل نموذج يحتوي <b>٨ اختيارات + ٨ صح/خطأ + سيناريو بثلاثة أجزاء</b>. كل سؤال وحل بالعربي والإنجليزي مع مرجع الشريحة.</p></div><div class="exam-route no-print"><a href="#set-A">Model A</a><a href="#set-B">Model B</a><a href="#set-C">Model C</a><label>Language · اللغة: <select id="langSel"><option value="both">Both · الاثنان</option><option value="en">English</option><option value="ar">العربية</option></select></label><button class="btn" onclick="revealAll()">Reveal all · الحلول</button><button class="btn primary" data-print>Print / PDF</button><span class="score" id="score"></span></div><div class="note"><div class="en"><b>Emergency plan:</b> Solve Model A, memorize all three scenario answers, then solve Models B and C. Finally open the cheat sheet. Do not spend your remaining time rereading every slide.</div><div class="ar"><b>خطة الطوارئ:</b> حل نموذج A، واحفظ إجابات السيناريوهات كلها، ثم حل B وC، وبعدها افتح الملخص. لا تضيع الوقت المتبقي في قراءة كل الشرائح من البداية.</div></div>''']
    for sid,title,ar_title,mcqs,tfs,scenarios in SETS:
        out.append(f'<section class="mock-set" id="set-{sid}"><div class="model-banner"><span>MODEL {sid}</span><div><h2>{title}</h2><p>{ar_title}</p></div></div><div class="qsec"><h2>Q1 · Circle the best answer</h2><div class="ar">س١ · اختر أفضل إجابة</div></div>')
        for i,q in enumerate(mcqs,1): out.append(qcard(f"{sid}-Q1.{i}",*q))
        out.append('<div class="qsec"><h2>Q2 · True or False</h2><div class="ar">س٢ · صح أم خطأ</div></div>')
        for i,(qe,qa,ans,ref,ee,ea) in enumerate(tfs,1):
            out.append(qcard(f"{sid}-Q2.{i}",qe,qa,[("True","صحيح"),("False","خطأ")],0 if ans else 1,ref,ee,ea,"True / False","tf"))
        out.append('<div class="qsec"><h2>Q3 · Scenario</h2><div class="ar">س٣ · السيناريو</div></div>')
        for n,qe,qa,ae,aa,ref in scenarios: out.append(short_card(f"{sid}-{n}",qe,qa,ae,aa,ref))
        out.append('</section>')
    out.append('''<div class="note"><div class="en"><b>Final warning:</b> These are high-confidence predictions, not a guarantee of the lecturer’s exact wording. Learn the reason behind every answer so you can handle changed wording.</div><div class="ar"><b>تنبيه أخير:</b> هذه توقعات قوية وليست ضماناً حرفياً لورقة المدرّسة. افهم سبب كل إجابة حتى تتعامل مع تغيير الصياغة.</div></div><div class="pager no-print"><a class="btn" href="exam.html">Solved photographed sample</a><a class="btn primary" href="cheatsheet.html">Final cheat sheet →</a></div></main><footer>Three focused predicted models · Chapters 1–4<div class="ar">ثلاثة نماذج متوقعة ومركزة · الفصول ١–٤</div></footer><script src="js/app.js"></script></body></html>''')
    (ROOT/'predicted.html').write_text(''.join(out),encoding='utf-8')
    print('wrote',ROOT/'predicted.html')

if __name__=='__main__': build()
